import contextlib
import io
import unittest

from textkit.cli import main
from textkit.mdtable import to_markdown


def run(argv, stdin_text):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err), \
            contextlib.redirect_stdin(io.StringIO(stdin_text)):
        code = main(argv)
    return code, out.getvalue(), err.getvalue()


class ToMarkdownTest(unittest.TestCase):
    def test_header_separator_and_rows(self):
        self.assertEqual(
            to_markdown([["a", "b"], ["1", "2"], ["3", "4"]]),
            "| a | b |\n| --- | --- |\n| 1 | 2 |\n| 3 | 4 |",
        )

    def test_header_only(self):
        self.assertEqual(to_markdown([["a"]]), "| a |\n| --- |")

    def test_strips_cells(self):
        self.assertEqual(
            to_markdown([[" a ", "b\t"], ["  1", "2 \n"]]),
            "| a | b |\n| --- | --- |\n| 1 | 2 |",
        )

    def test_escapes_pipes(self):
        self.assertEqual(
            to_markdown([["x|y", "z"], ["a | b", "|"]]),
            "| x\\|y | z |\n| --- | --- |\n| a \\| b | \\| |",
        )

    def test_no_rows_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([])

    def test_empty_header_raises(self):
        with self.assertRaises(ValueError):
            to_markdown([[]])

    def test_ragged_rows_raise(self):
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], ["1"]])
        with self.assertRaises(ValueError):
            to_markdown([["a", "b"], ["1", "2", "3"]])


class MdtableCliTest(unittest.TestCase):
    def test_prints_table_from_stdin(self):
        self.assertEqual(
            run(["mdtable"], "a,b\n1,2\n"),
            (0, "| a | b |\n| --- | --- |\n| 1 | 2 |\n", ""),
        )

    def test_quoted_pipe_is_escaped(self):
        code, out, _ = run(["mdtable"], 'a,b\n"x|y",2\n')
        self.assertEqual(code, 0)
        self.assertEqual(out, "| a | b |\n| --- | --- |\n| x\\|y | 2 |\n")

    def test_ragged_csv_exits_2(self):
        code, out, err = run(["mdtable"], "a,b\n1,2,3\n")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_empty_input_exits_2(self):
        code, out, err = run(["mdtable"], "")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

